/* Reads the public TGJU snapshot generated by GitHub Actions. No browser-side price APIs. */
(()=>{'use strict';
const DATA_URL='./data/market-rates.json',STALE_AFTER=15*60*1000;
const ITEMS=[
 {key:'usd',id:'priceUsd',timeId:'timeUsd',label:'دلار آزاد',kind:'irr'},
 {key:'eur',id:'priceEur',timeId:'timeEur',label:'یورو',kind:'irr'},
 {key:'gold',id:'priceGold',timeId:'timeGold',label:'طلای ۱۸ عیار',kind:'irr'},
 {key:'oil',id:'priceOil',timeId:'timeOil',label:'نفت برنت',kind:'usd'}
];
const fmt=n=>new Intl.NumberFormat('fa-IR',{maximumFractionDigits:2}).format(n);
const el=id=>document.getElementById(id);
function setValue(id,n,unit){const e=el(id);if(!e)return;e.textContent=n==null?'—':fmt(n);if(e.nextElementSibling)e.nextElementSibling.textContent=unit}
function tehranTime(value){const d=new Date(value);if(Number.isNaN(+d))return '';return new Intl.DateTimeFormat('fa-IR',{timeZone:'Asia/Tehran',month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}).format(d)}
function setTime(id,item,entry){
 const e=el(id);if(!e)return;
 if(!entry||!entry.fetchedAt){e.textContent='هنوز داده‌ای ثبت نشده';e.dataset.stale='true';return}
 const d=new Date(entry.fetchedAt),age=Date.now()-d.getTime(),stale=!Number.isFinite(+d)||age<0||age>STALE_AFTER;
 let label='دریافت از TGJU: '+tehranTime(entry.fetchedAt);
 if(entry.sourceDate)label+=' · تاریخ ثبت در TGJU: '+entry.sourceDate;
 if(stale)label+=' · هشدار: داده قدیمی است';
 e.textContent=label;e.dataset.stale=String(stale);
}
async function fetchMarketCurrencies(){
 const response=await fetch(DATA_URL+'?v='+Date.now(),{cache:'no-store',headers:{Accept:'application/json'}});
 if(!response.ok)throw Error('HTTP '+response.status);
 const data=await response.json(),items=data.items||{};
 let valid=0,stale=0;
 for(const item of ITEMS){
  const entry=items[item.key],raw=Number(entry&&entry.price);
  if(Number.isFinite(raw)&&raw>0){
   const price=item.kind==='irr'?raw/10:raw;
   setValue(item.id,price,item.kind==='irr'?(item.key==='gold'?'تومان / گرم':'تومان'):'دلار / بشکه');
   valid++;
   const fetched=Date.parse(entry.fetchedAt);
   if(!Number.isFinite(fetched)||Date.now()-fetched<0||Date.now()-fetched>STALE_AFTER)stale++;
  }else setValue(item.id,null,item.kind==='irr'?(item.key==='gold'?'تومان / گرم':'تومان'):'دلار / بشکه');
  setTime(item.timeId,item,entry);
 }
 setValue('priceGbp',null,'تومان');
 const gbpTime=el('timeGbp');if(gbpTime){gbpTime.textContent='در این نسخه از منبع TGJU دریافت نمی‌شود';gbpTime.dataset.stale='true'}
 const status=el('marketStatus');
 if(status){
  const checked=data.checkedAt?' · آخرین بررسی: '+tehranTime(data.checkedAt):'';
  status.textContent='منبع: TGJU مستقیم · داده موجود: '+valid+'/4'+(stale?' · قدیمی: '+stale:'')+checked;
 }
 return {valid,stale,errors:4-valid,checkedAt:data.checkedAt};
}
window.fetchMarketCurrencies=fetchMarketCurrencies;
})();